#!/usr/bin/env bash\nset -euo pipefail\n\n# Mock rationale: create temporary directory with known file sizes\nTMPDIR=$(mktemp -d)\ncleanup() {\n  rm -rf "$TMPDIR"\n}\ntrap cleanup EXIT\n\n# create files of specific sizes\ndd if=/dev/zero of="$TMPDIR/a.txt" bs=1K count=1 status=none\ndd if=/dev/zero of="$TMPDIR/b.txt" bs=1K count=2 status=none\ndd if=/dev/zero of="$TMPDIR/c.txt" bs=1K count=3 status=none\nmkdir -p "$TMPDIR/sub"\ndd if=/dev/zero of="$TMPDIR/sub/d.txt" bs=1K count=4 status=none\n\n# Run the utility\nOUTPUT=$(bash ../../src/main.sh -d "$TMPDIR" -n 3)\n\n# Verify that the top three entries are d.txt, c.txt, b.txt\necho "$OUTPUT" | grep -q "d.txt"\necho "$OUTPUT" | grep -q "c.txt"\necho "$OUTPUT" | grep -q "b.txt"\n\n# Ensure correct order\nfirst=$(echo "$OUTPUT" | head -n1 | awk '{print $2}')\nsecond=$(echo "$OUTPUT" | head -n2 | tail -n1 | awk '{print $2}')\nthird=$(echo "$OUTPUT" | head -n3 | tail -n1 | awk '{print $2}')\n\n[[ "$first" == "$TMPDIR/sub/d.txt" ]]\n[[ "$second" == "$TMPDIR/c.txt" ]]\n[[ "$third" == "$TMPDIR/b.txt" ]]\n\necho "All tests passed."
